function AdminAccount({user,onUser,show}:{user:User;onUser:()=>Promise<User|null>;show:(m:string,e?:boolean)=>void}){
 const[name,setName]=useState(user.name),[email,setEmail]=useState(user.email),[password,setPassword]=useState(''),[old,setOld]=useState(''),[next,setNext]=useState(''),[busy,setBusy]=useState(false);
 const updateAccount=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await put('/admin/account',{name,email,password});setPassword('');show('Nome e e-mail atualizados.');onUser()}catch(e:any){show(e.message,true)}finally{setBusy(false)}};
 const updatePassword=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await post('/account/password',{currentPassword:old,newPassword:next});show('Senha de administrador atualizada.');setOld('');setNext('')}catch(e:any){show(e.message,true)}finally{setBusy(false)}};
 return <><PageTitle title="Minha conta administrativa" subtitle="Gerencie seus dados e substitua a senha inicial por uma senha particular."/><div className="twoCol"><form className="panel adminForm" onSubmit={updateAccount}><h3>Dados do administrador</h3><Input label="Nome"><input value={name} onChange={e=>setName(e.target.value)}/></Input><Input label="E-mail de acesso"><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></Input><Input label="Confirme sua senha atual"><input required type="password" value={password} onChange={e=>setPassword(e.target.value)}/></Input><Button disabled={busy} type="submit">Atualizar dados <Save size={16}/></Button></form>
 <form className="panel adminForm" onSubmit={updatePassword}><h3>Trocar minha senha</h3><p className="muted">Por segurança, troque a senha de implantação antes de divulgar o aplicativo.</p><Input label="Senha atual"><input required type="password" value={old} onChange={e=>setOld(e.target.value)}/></Input><Input label="Nova senha (mínimo 8 caracteres)"><input required minLength={8} type="password" value={next} onChange={e=>setNext(e.target.value)}/></Input><Button disabled={busy} type="submit"><KeyRound size={16}/> Alterar minha senha</Button></form></div></>;
}

// --------------------- Parceria de saúde (sem dados clínicos expostos ao personal) ---------------------
type DoctorPublic={name:string;crm:string;title:string;whatsapp:string;discountPercent:number;instagram:string;facebook:string;website:string;articles:string;enabled:number};
const DOCTOR_FALLBACK:DoctorPublic={name:'Dr. Alison Martins',crm:'CRM-AM 6678',title:'Tratamento médico da obesidade e emagrecimento',whatsapp:'5592991177221',discountPercent:10,instagram:'https://www.instagram.com/dr.alison_martins?obrf=NDU5ODZnbmVkcXBk',facebook:'https://www.facebook.com/share/19rAPEqTnw/?mibextid=wwXIfr',website:'https://dr-alisonmartins.com.br',articles:'https://dr-alisonmartins.com.br/artigos/index.html',enabled:1};
function HealthCallout({navigate}:{navigate:(s:string)=>void}){return <div className="healthCallout"><div className="healthCalloutIcon"><HeartPulse size={32}/></div><div><span className="labelGold">PARCERIA SAÚDE E BEM-ESTAR</span><h3>Cuidar da saúde também é parte da sua evolução.</h3><p>Conheça o acompanhamento médico do Dr. Alison Martins e saiba como solicitar a primeira consulta.</p></div><Button variant="outline" onClick={()=>navigate('health')}>Conhecer atendimento <ArrowRight size={16}/></Button></div>}
function HealthPanel({user,show}:{user:User;show:(m:string,e?:boolean)=>void}){
 const[d,setD]=useState<DoctorPublic>(DOCTOR_FALLBACK),[linked,setLinked]=useState(false),[busy,setBusy]=useState(false),[loaded,setLoaded]=useState(false);
 useEffect(()=>{get<{doctor:DoctorPublic}>('/public/doctor').then(r=>setD(r.doctor||DOCTOR_FALLBACK)).catch(()=>{});get<{linked:boolean}>('/student/doctor-link').then(r=>{setLinked(r.linked);setLoaded(true)}).catch(()=>setLoaded(true))},[user.id]);
 const consent=async(v:boolean)=>{setBusy(true);try{await post('/student/doctor-link',{consent:v});setLinked(v);show(v?'Vínculo autorizado. O médico poderá criar seu plano alimentar.':'Vínculo com o médico revogado.')}catch(e:any){show(e.message,true)}finally{setBusy(false)}};
 const message=`Olá, Dr. Alison Martins! Meu nome é ${user.name} e sou aluno(a) da plataforma Wagner Noronha – Personal Trainer. Conheci seu atendimento pela plataforma e gostaria de agendar uma primeira consulta para avaliação médica relacionada à obesidade e ao emagrecimento. Também gostaria de utilizar a condição de ${d.discountPercent}% de desconto na primeira consulta divulgada na plataforma. Poderiam me informar os horários disponíveis e as orientações para agendamento?`;
 const whatsapp='https://wa.me/'+String(d.whatsapp||'').replace(/\D/g,'')+'?text='+encodeURIComponent(message);
 const social=[{title:'Instagram',icon:Instagram,url:d.instagram},{title:'Facebook',icon:Facebook,url:d.facebook},{title:'Site oficial',icon:Globe2,url:d.website},{title:'Artigos sobre saúde',icon:BookOpen,url:d.articles}];
 return <section className="healthPage"><PageTitle title="Saúde e Emagrecimento" subtitle="Conheça o atendimento médico parceiro e os conteúdos educativos."/>
  <article className="healthDoctor panel"><div className="healthDoctorHead"><div className="medicalAvatar"><Stethoscope size={42}/></div><div><span className="labelGold">ATENDIMENTO MÉDICO PARCEIRO</span><h2>{d.name}</h2><span className="healthCRM">MÉDICO · {d.crm}</span></div></div><h3>{d.title}</h3><p>Atendimento médico individualizado para avaliação e acompanhamento de condições relacionadas ao peso e ao emagrecimento. A consulta é agendada diretamente com a equipe médica.</p>
  <div className="healthOffer"><BadgeCheck size={21}/><div><strong>{d.discountPercent}% de desconto na primeira consulta</strong><small>Condição promocional sujeita às regras informadas pela equipe médica; não exige aquisição de plano de treino.</small></div></div>
  {d.enabled!==0?<a className="btn btn-primary healthWhatsapp" href={whatsapp} target="_blank" rel="noopener noreferrer"><MessageCircle size={21}/> Agendar consulta pelo WhatsApp <ExternalLink size={17}/></a>:<p className="muted">Agendamentos temporariamente indisponíveis.</p>}
  <p className="healthPrivacy">Ao abrir o WhatsApp, o texto já estará preenchido com seu nome e a origem Wagner Noronha. Confira a mensagem antes de enviar.</p>
  <h4>Conheça o Dr. Alison</h4><div className="healthLinks">{social.map(item=>{const I=item.icon;return <a key={item.title} href={item.url} target="_blank" rel="noopener noreferrer"><I size={24}/><span>{item.title}</span><ExternalLink size={15}/></a>})}</div></article>
  <article className="panel medicalConsent"><div className="panelHeader"><h3><Link2 size={19}/> Acompanhamento alimentar</h3></div><p>Se você já é paciente do Dr. Alison e deseja receber orientações alimentares pelo aplicativo, autorize o vínculo. Somente o médico poderá criar e consultar esses documentos. Você poderá revogar a autorização a qualquer momento.</p>
   <div className="consentRow"><span className={'consentDot '+(linked?'enabled':'')}/><b>{!loaded?'Consultando autorização...':linked?'Vínculo médico autorizado':'Nenhum vínculo autorizado'}</b></div>
   {loaded&&(linked?<Button variant="outline" disabled={busy} onClick={()=>{if(confirm('Revogar autorização para que o Dr. Alison acesse seu cadastro e mantenha o vínculo no aplicativo?'))void consent(false)}}>Revogar autorização</Button>:<Button disabled={busy} onClick={()=>{if(confirm('Autoriza o Dr. Alison a visualizar seu nome, e-mail e a criar e consultar seus planos alimentares nesta plataforma?'))void consent(true)}}><ShieldCheck size={17}/> Autorizar vínculo com Dr. Alison</Button>)}
  </article><p className="disclaimer">Conteúdo informativo. O atendimento médico é independente do treinamento e depende de avaliação clínica individualizada.</p></section>
}
function StudentDiet({user,active,show}:{user:User;active:boolean;show:(m:string,e?:boolean)=>void}){
 const[plans,setPlans]=useState<any[]>([]),[legacy,setLegacy]=useState<any[]>([]),[opened,setOpened]=useState<number|null>(null);
 useEffect(()=>{get<{items:any[]}>('/student/medical-plans').then(r=>setPlans(r.items)).catch(e=>show(e.message,true));if(active)get<any>('/student/content').then(r=>setLegacy(r.diet||[])).catch(()=>{})},[user.id,active]);
 const openPDF=async(id:number)=>{try{const url=await previewPrivate(`/medical/plans/${id}/pdf`);window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),120000);}catch(e:any){show(e.message,true)}};
 return <section><PageTitle title="Minha dieta" subtitle="Seus planos e orientações alimentares, com acesso reservado."/>
 {plans.length>0?<div className="medicalPlansList">{plans.map(p=><article className="panel medicalPlanCard" key={p.id}><div className="panelHeader"><div><span className="labelGold">PLANO DO DR. ALISON · VERSÃO {p.version}</span><h3>{p.title}</h3><small>Publicado: {formatDateTime(p.publishedAt)}</small></div><span className="status status-approved">Disponível</span></div><p>{p.overview}</p><div className="medicalActions"><Button variant="outline" onClick={()=>setOpened(opened===p.id?null:p.id)}>{opened===p.id?'Ocultar':'Visualizar refeições'} <ChevronDown size={16}/></Button>{p.pdfName&&<Button variant="outline" onClick={()=>openPDF(p.id)}><FileText size={16}/> Abrir PDF</Button>}</div>{opened===p.id&&<div className="medicalMeals">{JSON.parse(p.mealsJson||'[]').map((meal:any,i:number)=><div className="medicalMeal" key={i}><span className="mealTime">{meal.time||'—'}</span><strong>{meal.title}</strong><p>{meal.description}</p></div>)}</div>}</article>)}</div>:<Empty title="Ainda não há plano médico publicado" description="Se você já é paciente, autorize o vínculo na aba Saúde e Emagrecimento. O médico poderá disponibilizar suas orientações aqui." icon={Utensils}/>}
 {legacy.length>0&&<><h3 className="sectionLegacy">Orientações anteriores</h3><div className="gridCards">{legacy.map((d:any)=><article className="panel mealCard" key={d.id}><span className="mealTime">{d.time||'Refeição'}</span><h3>{d.title}</h3><p>{d.description}</p></article>)}</div></>}
 <p className="disclaimer">Os documentos clínicos são restritos ao paciente e ao profissional responsável. Não compartilhe informações de saúde sem necessidade.</p></section>
}
function DoctorPublicSettings({show}:{show:(m:string,e?:boolean)=>void}){
 const[d,setD]=useState<DoctorPublic>(DOCTOR_FALLBACK),[busy,setBusy]=useState(false);
 useEffect(()=>{get<{doctor:DoctorPublic}>('/admin/doctor-public').then(r=>setD(r.doctor||DOCTOR_FALLBACK)).catch(e=>show(e.message,true))},[]);
 const field=(key:keyof DoctorPublic,label:string)=> <Input label={label}><input value={String(d[key]??'')} onChange={e=>setD({...d,[key]:e.target.value})}/></Input>;
 const save=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await put('/admin/doctor-public',d);show('Dados públicos da parceria atualizados.')}catch(e:any){show(e.message,true)}finally{setBusy(false)}};
 return <section><PageTitle title="Parceria · Dr. Alison Martins" subtitle="Configure os links públicos, WhatsApp e desconto. O administrador não acessa documentos clínicos dos pacientes."/>
  <form className="panel adminForm medicalSettings" onSubmit={save}><h3>Informações públicas do médico</h3><div className="formGrid">{field('whatsapp','WhatsApp com DDI + DDD (ex.: 555592991177221)')}{field('discountPercent','Desconto na primeira consulta (%)')}{field('instagram','Instagram')}{field('facebook','Facebook')}{field('website','Site oficial')}{field('articles','Artigos')}</div><label className="consentCheck"><input type="checkbox" checked={!!d.enabled} onChange={e=>setD({...d,enabled:e.target.checked?1:0})}/> Divulgação e agendamento habilitados</label><p className="muted">Antes da publicação, confirme com o médico o número, a condição de desconto e os dados de registro profissional.</p><Button type="submit" disabled={busy}><Save size={16}/> Salvar parceria</Button></form></section>
}
function DoctorPortal({page,user,show}:{page:string;user:User;show:(m:string,e?:boolean)=>void}){
 const[patients,setPatients]=useState<any[]>([]),[plans,setPlans]=useState<any[]>([]),[selected,setSelected]=useState(0),[title,setTitle]=useState(''),[overview,setOverview]=useState(''),[meals,setMeals]=useState<any[]>([{time:'07:00',title:'Café da manhã',description:''}]),[busy,setBusy]=useState(false),[openEdit,setOpenEdit]=useState<number|null>(null),[oldPass,setOldPass]=useState(''),[newPass,setNewPass]=useState('');
 const load=()=>{get<{items:any[]}>('/doctor/patients').then(r=>setPatients(r.items)).catch(e=>show(e.message,true));get<{items:any[]}>('/doctor/plans').then(r=>setPlans(r.items)).catch(e=>show(e.message,true))};useEffect(load,[]);
 const save=async(e:React.FormEvent)=>{e.preventDefault();if(!selected){show('Selecione um paciente autorizado.',true);return;}setBusy(true);try{if(openEdit){await put(`/doctor/plans/${openEdit}`,{title,overview,meals});show('Rascunho atualizado.')}else{await post('/doctor/plans',{studentId:selected,title,overview,meals});show('Novo rascunho salvo.')}setOpenEdit(null);setTitle('');setOverview('');setMeals([{time:'07:00',title:'Café da manhã',description:''}]);load()}catch(e:any){show(e.message,true)}finally{setBusy(false)}};
 const edit=(p:any)=>{setOpenEdit(p.id);setSelected(p.studentId);setTitle(p.title);setOverview(p.overview);setMeals(JSON.parse(p.mealsJson||'[]'));window.scrollTo({top:0,behavior:'smooth'})};
 const pdfUpload=async(id:number,file?:File)=>{if(!file)return;try{await upload(`/doctor/plans/${id}/pdf`,file);show('PDF enviado com segurança.');load()}catch(e:any){show(e.message,true)}};
 const publish=async(id:number)=>{if(!confirm('Publicar este plano para o aluno? Após publicar, novas alterações exigirão uma nova versão.'))return;try{await post(`/doctor/plans/${id}/publish`,{});show('Plano publicado para o paciente.');load()}catch(e:any){show(e.message,true)}};
 const openPDF=async(id:number)=>{try{const url=await previewPrivate(`/medical/plans/${id}/pdf`);window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),120000)}catch(e:any){show(e.message,true)}};
 if(page==='doctor-account')return <section><PageTitle title="Segurança do acesso médico" subtitle="Altere a senha inicial para uma senha exclusiva."/><form className="panel adminForm" onSubmit={async e=>{e.preventDefault();try{await post('/account/password',{currentPassword:oldPass,newPassword:newPass});setOldPass('');setNewPass('');show('Senha atualizada.')}catch(err:any){show(err.message,true)}}}><Input label="Senha atual"><input type="password" required value={oldPass} onChange={e=>setOldPass(e.target.value)}/></Input><Input label="Nova senha (mínimo 8 caracteres)"><input required type="password" minLength={8} value={newPass} onChange={e=>setNewPass(e.target.value)}/></Input><Button type="submit"><KeyRound size={16}/> Alterar senha</Button></form></section>;
 return <section className="doctorPortal"><PageTitle title={page==='doctor-home'?'Painel médico · Dr. Alison Martins':'Planos alimentares dos pacientes'} subtitle="Apenas alunos que autorizaram o vínculo aparecem neste painel." action={<Button variant="outline" onClick={load}><RefreshCw size={16}/> Atualizar</Button>}/><div className="doctorStats"><Stat icon={Users} label="Pacientes autorizados" value={String(patients.length)}/><Stat icon={ClipboardList} label="Planos cadastrados" value={String(plans.length)}/><Stat icon={FileCheck2} label="Publicados" value={String(plans.filter(p=>p.status==='PUBLISHED').length)}/></div>
 {page==='doctor-home'?<div className="panel"><h3>Pacientes vinculados</h3>{patients.length?patients.map(p=><div className="doctorPatientRow" key={p.id}><span className="userBadge">{p.name[0]}</span><div><strong>{p.name}</strong><small>{p.email}</small></div><span className="labelGold">AUTORIZADO</span></div>):<Empty title="Aguardando vínculo" description="Os alunos devem autorizar o vínculo em Saúde e Emagrecimento antes de você visualizar seus cadastros." icon={Stethoscope}/>}<p className="disclaimer">Este painel não compartilha os documentos clínicos com a administração do personal.</p></div>:<><form className="panel doctorEditor" onSubmit={save}><div className="panelHeader"><h3>{openEdit?'Editar rascunho':'Novo plano alimentar / orientações'}</h3><Stethoscope size={23}/></div><Input label="Selecionar paciente autorizado"><select required value={selected} onChange={e=>setSelected(Number(e.target.value))} disabled={!!openEdit}><option value={0}>Selecione o paciente...</option>{patients.map(p=><option key={p.id} value={p.id}>{p.name} · {p.email}</option>)}</select></Input><Input label="Título do documento"><input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="Ex.: Plano de acompanhamento alimentar"/></Input><Input label="Orientações gerais"><textarea rows={4} value={overview} onChange={e=>setOverview(e.target.value)} placeholder="Informações individualizadas, recomendações e observações..."/></Input>
 <h4>Refeições e horários</h4><div className="doctorMealsEditor">{meals.map((m,i)=><div className="doctorMealEditor" key={i}><div className="formGrid"><Input label="Horário"><input type="time" value={m.time||''} onChange={e=>setMeals(v=>v.map((x,j)=>j===i?{...x,time:e.target.value}:x))}/></Input><Input label="Refeição"><input value={m.title||''} onChange={e=>setMeals(v=>v.map((x,j)=>j===i?{...x,title:e.target.value}:x))} placeholder="Café da manhã..."/></Input></div><Input label="Descrição, quantidades e observações"><textarea rows={3} value={m.description||''} onChange={e=>setMeals(v=>v.map((x,j)=>j===i?{...x,description:e.target.value}:x))}/></Input><Button variant="ghost" onClick={()=>setMeals(v=>v.filter((_,j)=>j!==i))} disabled={meals.length===1}><Trash2 size={15}/> Remover refeição</Button></div>)}</div>
 <div className="medicalActions"><Button variant="outline" disabled={meals.length>=15} onClick={()=>setMeals(v=>[...v,{time:'',title:'',description:''}])}><Plus size={17}/> Adicionar refeição</Button><Button disabled={busy} type="submit"><Save size={17}/> {openEdit?'Salvar alterações':'Salvar rascunho'}</Button>{openEdit&&<Button variant="ghost" onClick={()=>{setOpenEdit(null);setTitle('');setOverview('')}}>Cancelar edição</Button>}</div></form>
 <div className="medicalPlansList">{plans.length?plans.map(p=><article className="panel medicalPlanCard" key={p.id}><div className="panelHeader"><div><span className="labelGold">VERSÃO {p.version} · {p.studentName}</span><h3>{p.title}</h3><small>{p.status==='PUBLISHED'?'Publicado em '+formatDateTime(p.publishedAt):'Rascunho - não visível ao aluno'}</small></div><span className={'status '+(p.status==='PUBLISHED'?'status-approved':'status-awaiting_proof')}>{p.status==='PUBLISHED'?'Publicado':'Rascunho'}</span></div><p>{p.overview}</p><div className="medicalActions">{p.status==='DRAFT'&&<><Button variant="outline" onClick={()=>edit(p)}>Editar</Button><label className="btn btn-outline fileUpload"><Upload size={16}/> {p.pdfName?'Substituir PDF':'Anexar PDF'}<input type="file" accept="application/pdf" onChange={e=>pdfUpload(p.id,e.target.files?.[0])}/></label><Button onClick={()=>publish(p.id)}><Check size={16}/> Publicar</Button></>}{p.pdfName&&<Button variant="outline" onClick={()=>openPDF(p.id)}><FileText size={16}/> Ver PDF</Button>}</div></article>):<Empty title="Nenhum plano cadastrado" description="Selecione um paciente autorizado e salve o primeiro rascunho." icon={ClipboardList}/>}</div></>}
 </section>
}

createRoot(document.getElementById('root')!).render(<App/>);
